Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQARSS.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Definition SCR : Z := 14336.                       (* [comment removed for export] *)
Definition mparser_at := (PQMA.mparser_at RSEGS PMA.AD PMSPA.accA PMSPA.annA (pa_vp_parser PMA.AD)).

(* [comment removed for export] *)
Definition vs_clear (x : PM.vstr) : PM.vstr := match x with PM.VShort _ => PM.VShort 0 | PM.VLong c _ p => PM.VLong c 0 p end.
Definition st1 (s : PQMA.mpst) : PQMA.mpst :=
  PQMA.MPST 1 0 (PQMA.p_depth s) (PQMA.p_src s) (vs_clear (PQMA.p_tb s)) (PQMA.p_tg s) (PGV8.v8_clear (PQMA.p_bb s)) (PQMA.p_bg s)
            (PQMA.p_sb s) (PQMA.p_sk s) (PQMA.p_stk s).
Definition st2 (s : PQMA.mpst) : PQMA.mpst :=
  PQMA.MPST 1 0 (PQMA.p_depth s) (PQMA.p_src s) (vs_clear (PQMA.p_tb s)) (PQMA.p_tg s) (PGV8.v8_clear (PQMA.p_bb s)) (PQMA.p_bg s)
            (PQMA.p_sb s) (PQMA.p_sk s) [].

Section Call.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Variables (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet).
Variables (LBX : list (Z * Z)) (FF LK0 : list fframe) (Aw0 : list (Z * Z)) (cr : credit) (sp r fb : Z) (s : PQMA.mpst).

Definition op : Z := fb + 592.
(* [comment removed for export] *)
Definition W : list L5.range := [(op + 8, 8); (op + 328, 24); (op + 352, 24); (op + 376, 24)].

(* [comment removed for export] *)
Definition pre : Prop :=
  ri_inv HI (PQMA.mparser_own s ++ LBX) FF LK0 cr Aw0 M0 (vml_of model0) /\ L5CA.amodel_ok Aw0 model0 /\ K [] /\ PMSPA.entryA PMA.AD L ar R0 M0 sp r 1
  /\ PGSA.ffroomB PQRA.FCM 1 FF LK0 /\ PMSPA.ffrsA FF sp /\ PQRA.frame_okM FF fb
  /\ getr R0 (reg 10) = Z_to_bv 64 op /\ mparser_at M0 op (fb + 96) s /\ PMSPA.accA M0 op 400 /\ PMSTA.base_okA RSEGS PMA.AD M0.

(* [comment removed for export] *)
Definition kont : Prop :=
  forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
    regs_preserved R0 R' -> mparser_at M' op (fb + 96) (PQRA.mpst_reset s) ->
    L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 1) W M0 M' ->
    model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI (PQMA.mparser_own s ++ LBX) FF LK' cr Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx') R' r M' model') K.

(* [comment removed for export] *)
Definition saves (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (sp - 8) (bv_unsigned (getr R0 (reg 1))) /\ L5.u64_at RSEGS M (sp - 16) (bv_unsigned (getr R0 (reg 8)))
  /\ L5.u64_at RSEGS M (sp - 24) (bv_unsigned (getr R0 (reg 9))) /\ L5.u64_at RSEGS M (sp - 32) (bv_unsigned (getr R0 (reg 18))).

(* [comment removed for export] *)
Definition smid (sk : PQMA.mpst) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (LK : list fframe) (Aw : list (Z * Z)) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (sp - 48) /\ getr R (reg 8) = Z_to_bv 64 op /\ getr R (reg 18) = Z_to_bv 64 2147450880
  /\ (forall k, In k [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat -> getr R (reg k) = getr R0 (reg k))
  /\ saves M /\ mparser_at M op (fb + 96) sk /\ PMSPA.accA M op 400 /\ PMSTA.base_okA RSEGS PMA.AD M
  /\ L5CA.astk ar M sp SCR /\ shadow_zero M (sp - SCR) (SCR / 8)
  /\ ri_inv HI (PQMA.mparser_own s ++ LBX) FF LK cr Aw M (vml_of model) /\ L5CA.amodel_ok Aw model /\ model_rt model0 model /\ incl LK LK0 /\ incl Aw0 Aw
  /\ L5SAR.ek L ar LBX FF sp SCR W M0 M /\ L5SAR.dk L ar LBX FF sp SCR M0 M.

Definition smid1 := smid (st1 s).                                                          (* [comment removed for export] *)
Definition smid2 R M model LK Aw := smid (st2 s) R M model LK Aw /\ getr R (reg 9) = Z_to_bv 64 (op + 376).   (* [comment removed for export] *)
End Call.

(* [comment removed for export] *)
Lemma own_st1 s : PQMA.mparser_own (st1 s) = PQMA.mparser_own s.
Proof. destruct s as [mo dn dp src tb tg bb bg sb sk stk]. unfold st1, PQMA.mparser_own, PQMA.mrest_own. cbn [PQMA.p_src PQMA.p_bb PQMA.p_tb PQMA.p_sb PQMA.p_sk]. destruct bb, tb; reflexivity. Qed.
Lemma own_st2 s : PQMA.mparser_own (st2 s) = PQMA.mparser_own s.
Proof. destruct s as [mo dn dp src tb tg bb bg sb sk stk]. unfold st2, PQMA.mparser_own, PQMA.mrest_own. cbn [PQMA.p_src PQMA.p_bb PQMA.p_tb PQMA.p_sb PQMA.p_sk]. destruct bb, tb; reflexivity. Qed.

Section Glue.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).

(* [comment removed for export] *)
Definition head_stmt : Prop :=
  PNSAX.ann_shrink_v8_spec RSEGS PMA.AD L ar HI 0xc1550 ->
  forall (fx : FPState) R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s,
    pre L ar HI R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s ->
    (forall (fx1 : FPState) R1 M1 model1 LK1 Aw1, smid1 L ar HI R0 M0 model0 LBX FF LK0 Aw0 cr sp fb s R1 M1 model1 LK1 Aw1 ->
        srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx1) R1 0xcfca0 M1 model1) K) ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R0 0xcfb7c M0 model0) K.
(* [comment removed for export] *)
Definition mids_stmt : Prop :=
  PQSAXQ.ann_shrink_spec RSEGS PMA.AD L ar HI 0xc0f48 ->
  forall (fx : FPState) R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s R1 M1 model1 LK1 Aw1,
    pre L ar HI R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s ->
    smid1 L ar HI R0 M0 model0 LBX FF LK0 Aw0 cr sp fb s R1 M1 model1 LK1 Aw1 ->
    (forall (fx2 : FPState) R2 M2 model2 LK2 Aw2, smid2 L ar HI R0 M0 model0 LBX FF LK0 Aw0 cr sp fb s R2 M2 model2 LK2 Aw2 ->
        srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 0xcfcf0 M2 model2) K) ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R1 0xcfca0 M1 model1) K.
(* [comment removed for export] *)
Definition tail_stmt : Prop :=
  PQSAXQ.push_root_spec RSEGS PMA.AD L ar HI 0xcf178 ->
  forall (fx : FPState) R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s R2 M2 model2 LK2 Aw2,
    pre L ar HI R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s ->
    smid2 L ar HI R0 M0 model0 LBX FF LK0 Aw0 cr sp fb s R2 M2 model2 LK2 Aw2 ->
    kont L ar HI R0 M0 model0 K LBX FF LK0 Aw0 cr sp r fb s ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R2 0xcfcf0 M2 model2) K.

Theorem reset_of_stages : head_stmt -> mids_stmt -> tail_stmt ->
  PNSAX.ann_shrink_v8_spec RSEGS PMA.AD L ar HI 0xc1550 -> PQSAXQ.ann_shrink_spec RSEGS PMA.AD L ar HI 0xc0f48 ->
  PQSAXQ.push_root_spec RSEGS PMA.AD L ar HI 0xcf178 -> PQRAa.reset_spec L ar HI.
Proof.
  intros HEAD MIDS TAIL ASH8 ASH PSH. unfold PQRAa.reset_spec, PQRA.reset_spec.
  intros fx R M model K LBX FF LK Aw cr sp r fb s HH AM K0 ENT FRM FRS SP16 FOK A10 PA ACC BASE KONT.
  assert (PRE : pre L ar HI R M model K LBX FF LK Aw cr sp r fb s).
  { exact (conj HH (conj AM (conj K0 (conj ENT (conj FRM (conj FRS (conj FOK (conj A10 (conj PA (conj ACC BASE)))))))))). }
  apply (HEAD ASH8 fx R M model K LBX FF LK Aw cr sp r fb s PRE).
  intros fx1 R1 M1 model1 LK1 Aw1 MID1.
  apply (MIDS ASH fx1 R M model K LBX FF LK Aw cr sp r fb s R1 M1 model1 LK1 Aw1 PRE MID1).
  intros fx2 R2 M2 model2 LK2 Aw2 MID2.
  exact (TAIL PSH fx2 R M model K LBX FF LK Aw cr sp r fb s R2 M2 model2 LK2 Aw2 PRE MID2 KONT).
Qed.
End Glue.
End PQARSS.

End PnARstStmts.
