(* [comment removed for export] *)
Lemma ddq_run (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (A B : Z) :
  getr R (reg 11) = Z_to_bv 64 A -> getr R (reg 12) = Z_to_bv 64 B -> getr R (reg 13) = Z_to_bv 64 TEN19 ->
  1 <= A <= 2 ^ 30 -> 0 <= B < 2 ^ 64 ->
  exists fx' R', msteps RSEGS (st fx R DDQ M) (st fx' R' DDQ_X M)
    /\ (forall x, In x KSQ -> getr R' (reg x) = getr R (reg x))
    /\ getr R' (reg 10) = Z_to_bv 64 0 /\ getr R' (reg 12) = Z_to_bv 64 ((A * 2 ^ 64 + B) / TEN19).
Proof.
